catalog_script_client.script:
function onSubmit() {

	if (g_scratchpad.isFormValid)
        return true;
	var actionName = g_form.getActionName();

   var trainingDate = g_form.getValue('training_schedules');
    console.log("Valor data função check: " + trainingDate);

    var trainingNameSysId = g_form.getValue('choose_the_training_that_you_want_to_enroll_in');
    console.log("(Submit) - Rodou e temos o training: " + trainingNameSysId);

    // Pega o sys_id do usuário atual
    var userId = g_user.userID;
    console.log("(Submit) - UserId: " + userId);

	formSubmitted = true;

    // Chama a função assíncrona e lida com a resposta
    checkUserParticipationInTraining(trainingNameSysId, userId, trainingDate)
        .then(function(isUserAlreadyParticipate) {
            console.log("(Submit) - Valor de retorno da função: " + isUserAlreadyParticipate);

            if (isUserAlreadyParticipate === 'true') {
                alert('Você já está matriculado neste treinamento. Não é possível se matricular novamente.');
                //g_form.clearOptions('training_schedules');
                //return false; // Impede o envio do formulário
            } else {
				console.log("Usuário não está matriculado. Prosseguindo com a inscrição.");
				g_scratchpad.isFormValid = true;
                g_form.submit(actionName); // Envia o formulário manualmente

                // Continua com o envio do formulário

				//formSubmitted = false;
               	// return true;
            }
        })
        .catch(function(error) {
            console.error("Erro ao verificar participação do usuário: " + error);
            alert("Ocorreu um erro ao verificar sua matrícula. Tente novamente.");
            //return false; // Impede o envio do formulário em caso de erro
        });


	return false;		
}

// Função assíncrona com Promise
function checkUserParticipationInTraining(trainingNameSysId, userId, trainingDate) {
    return new Promise(function(resolve, reject) {
        var gaRegistration = new GlideAjax('AooPemyUtilsAjax');
        gaRegistration.addParam('sysparm_name', 'isUserRegistered');
        gaRegistration.addParam('sysparm_training_date', trainingDate);
        gaRegistration.addParam('sysparm_training_name', trainingNameSysId);
        gaRegistration.addParam('sysparm_user', userId);

        gaRegistration.getXMLAnswer(function(registrationResponse) {
            console.log("(Submit) Response: " + registrationResponse);
            resolve(registrationResponse); // Resolve a Promise com a resposta
        });
    });

}
